actions.sql:
SELECT COALESCE(SUM(
  (COALESCE(o.c_wqjsib, 0) * o.c_rzbauk / 100.0) - COALESCE(r.total_refund, 0)
), 0) AS total_net_value
FROM r_hpafrs o
LEFT JOIN (
  SELECT c_uminvw, SUM(c_euidtu) / 100.0 AS total_refund
  FROM r_ubutws
  GROUP BY c_uminvw
) r ON o.c_aivsmt = r.c_uminvw
WHERE o.c_zcbtst = 'web';

